class Solution:
    def minDistance(self, word1: str, word2: str) -> int:
        n = len(word2)
        dp = [n - j for j in range(n + 1)]
        for i in range(len(word1) - 1, -1, -1):
            next_diag = dp[n]
            dp[n] = len(word1) - i
            for j in range(n - 1, -1, -1):
                old = dp[j]
                if word1[i] == word2[j]:
                    dp[j] = next_diag
                else:
                    dp[j] = 1 + min(dp[j], dp[j + 1], next_diag)
                next_diag = old
        return dp[0]

